import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"愍命","description":"","frontmatter":{"title":"愍命","date":"2026-11-24T00:00:00.000Z","seq":54,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"刘向","source_book":"楚辞","prev":{"text":"忧苦","link":"/blogs/楚辞/忧苦.html"},"next":{"text":"思古","link":"/blogs/楚辞/思古.html"}},"headers":[],"relativePath":"blogs/楚辞/愍命.md","filePath":"blogs/楚辞/愍命.md"}'),o={name:"blogs/楚辞/愍命.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="愍命" tabindex="-1">愍命 <a class="header-anchor" href="#愍命" aria-label="Permalink to &quot;愍命&quot;">​</a></h1><p class="poem-meta">先秦 · 刘向　·　九叹</p><div class="poem"><p class="poem-stanza">昔皇考之嘉志兮，喜登能而亮贤。</p><p class="poem-stanza">情纯洁而罔薉兮，姿盛质而无愆。</p><p class="poem-stanza">放佞人与谄谀兮，斥谗夫与便嬖。</p><p class="poem-stanza">亲忠正之悃诚兮，招贞良与明智。</p><p class="poem-stanza">心溶溶其不可量兮，情澹澹其若渊。</p><p class="poem-stanza">回邪辟而不能入兮，诚原藏而不可迁。</p><p class="poem-stanza">逐下袟于後堂兮，迎虙妃于伊雒。</p><p class="poem-stanza">刜谗贼于中廇兮，选吕管于榛薄。</p><p class="poem-stanza">丛林之下无怨士兮，江河之畔无隐夫。</p><p class="poem-stanza">三苗之徒以放逐兮，伊皋之伦以充庐。</p><p class="poem-stanza">今反表以为里兮，颠裳以为衣。</p><p class="poem-stanza">戚宋万于两楹兮，废周邵于遐夷。</p><p class="poem-stanza">却骐骥以转运兮，腾驴骡以驰逐。</p><p class="poem-stanza">蔡女黜而出帷兮，戎妇入而綵绣服。</p><p class="poem-stanza">庆忌囚于阱室兮，陈不占战而赴围。</p><p class="poem-stanza">破伯牙之号钟兮，挟人筝而弹纬。</p><p class="poem-stanza">藏瑉石于金匮兮，捐赤瑾于中庭。</p><p class="poem-stanza">韩信蒙于介胄兮，行夫将而攻城。</p><p class="poem-stanza">莞芎弃于泽洲兮，瓟瓥蠹于筐簏。</p><p class="poem-stanza">麒麟奔于九皋兮，熊罴群而逸囿。</p><p class="poem-stanza">折芳枝与琼华兮，树枳棘与薪柴。</p><p class="poem-stanza">掘荃蕙与射干兮，耘藜藿与蘘荷。</p><p class="poem-stanza">惜今世其何殊兮，远近思而不同。</p><p class="poem-stanza">或沉沦其无所达兮，或清激其无所通。</p><p class="poem-stanza">哀余生之不当兮，独蒙毒而逢尤。</p><p class="poem-stanza">虽謇謇以申志兮，君乖差而屏之。</p><p class="poem-stanza">诚惜芳之菲菲兮，反以兹为腐也。</p><p class="poem-stanza">怀椒聊之蔎蔎兮，乃逢纷以罹诟也。</p><p class="poem-stanza">叹曰：</p><p class="poem-stanza">嘉皇既殁终不返兮，山中幽险郢路远兮。</p><p class="poem-stanza">谗人諓諓孰可愬兮，征夫罔极谁可语兮。</p><p class="poem-stanza">行吟累欷声喟喟兮，怀忧含戚何侘傺兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
